from dataclasses import dataclass
from typing import Iterable, Optional

@dataclass(frozen=True)
class Job:
    job_id: str
    priority: int
    submitted_at: int
    state: str

def order_key(job: Job):
    return (-job.priority, job.submitted_at, job.job_id)

def select_next(jobs: Iterable[Job], running: int, capacity: int) -> Optional[Job]:
    if running >= capacity:
        return None
    queued = [job for job in jobs if job.state == 'queued']
    return min(queued, key=order_key, default=None)

