from dataclasses import dataclass, field
from typing import Deque, Optional

@dataclass
class Queue:
    pending: Deque[str] = field(default_factory=deque)
    active: int = 0
    limit: int = 1

class Scheduler:
    def __init__(self, queues: dict[str, Queue]):
        self.queues = queues
        self.last_selected: Optional[str] = None

    def dispatch_next(self) -> Optional[tuple[str, str]]:
        eligible = sorted(
            name for name, queue in self.queues.items()
            if queue.pending and queue.active < queue.limit
        )
        if not eligible:
            return None
        if self.last_selected is None:
            name = eligible[0]
        else:
            name = next((candidate for candidate in eligible if candidate > self.last_selected), eligible[0])
        job_id = self.queues[name].pending.popleft()
        self.queues[name].active += 1
        self.last_selected = name
        return name, job_id

from collections import deque
from dataclasses import dataclass, field
from typing import Deque, Optional

@dataclass
class Job:
    job_id: str
    cost: float

@dataclass
class Queue:
    name: str
    weight: float
    virtual_finish: float
    pending: Deque[Job] = field(default_factory=deque)
    running: int = 0
    max_running: int = 1

def choose_queue(queues: list[Queue]) -> Optional[Queue]:
    eligible = [q for q in queues if q.pending and q.running < q.max_running]
    return min(eligible, key=lambda q: (q.virtual_finish, q.name), default=None)

def dispatch(queues: list[Queue]):
    queue = choose_queue(queues)
    if queue is None:
        return None
    job = queue.pending.popleft()
    queue.running += 1
    queue.virtual_finish += job.cost / queue.weight
    return queue.name, job.job_id
